begin read only;
set local statement_timeout='5s';
select clock_timestamp() observed_at,
 (select jsonb_build_object('enabled',enabled,'ceiling_microusd',ceiling_microusd,'reserved_microusd',reserved_microusd,'reservation_cap_enforced',reservation_cap_enforced) from private.ai_test_budget_v5 where singleton) budget,
 (select jsonb_agg(jsonb_build_object('version',version,'name',name,'statement_count',coalesce(array_length(statements,1),0),'source_md5',md5(array_to_string(statements,E'\n')),'mentions_ceiling',array_to_string(statements,E'\n') ilike '%ceiling_microusd%','has_100m_literal',array_to_string(statements,E'\n') like '%100000000%','mentions_budget_constraint',array_to_string(statements,E'\n') ilike '%ai_test_budget_v5_%check%') order by version)
 from supabase_migrations.schema_migrations where array_to_string(statements,E'\n') ilike '%ai_test_budget_v5%' or array_to_string(statements,E'\n') ilike '%ceiling_microusd%') budget_related_migration_metadata,
 (select jsonb_agg(jsonb_build_object('name',conname,'type',contype,'definition',pg_get_constraintdef(oid)) order by conname) from pg_constraint where conrelid='private.ai_test_budget_v5'::regclass) budget_constraints,
 (select jsonb_agg(jsonb_build_object('column',column_name,'type',data_type,'default',column_default) order by ordinal_position) from information_schema.columns where table_schema='private' and table_name='ai_test_budget_v5') budget_columns,
 (select jsonb_agg(jsonb_build_object('trigger',tgname,'function',tgfoid::regprocedure::text,'enabled',tgenabled)) from pg_trigger where tgrelid='private.ai_test_budget_v5'::regclass and not tgisinternal) budget_triggers,
 (select jsonb_agg(jsonb_build_object('schema',table_schema,'table',table_name,'columns',columns) order by table_schema,table_name) from(
 select table_schema,table_name,array_agg(column_name order by ordinal_position) columns
 from information_schema.columns where table_schema in('private','public') and (table_name ilike '%audit%' or table_name ilike '%budget%history%' or table_name ilike '%budget%change%')
 group by table_schema,table_name)x) audit_relation_metadata;
rollback;

begin read only;
set local statement_timeout='5s';
select clock_timestamp() observed_at,
 jsonb_build_object('total',(select count(*) from supabase_migrations.schema_migrations),'with_sql',(select count(*) from supabase_migrations.schema_migrations where coalesce(cardinality(statements),0)>0),'without_sql',(select count(*) from supabase_migrations.schema_migrations where coalesce(cardinality(statements),0)=0),'any_sql_with_100m_literal',(select count(*) from supabase_migrations.schema_migrations where array_to_string(statements,E'\n') like '%100000000%')) migration_source_coverage,
 (select jsonb_agg(jsonb_build_object('version',version,'name',name,'has_sql',coalesce(cardinality(statements),0)>0,'mentions_budget',coalesce(array_to_string(statements,E'\n') ilike '%ai_test_budget_v5%',false),'mentions_ceiling',coalesce(array_to_string(statements,E'\n') ilike '%ceiling_microusd%',false)) order by version) from supabase_migrations.schema_migrations where version>'20261109014646') migrations_after_last_5usd_evidence,
 current_setting('track_commit_timestamp') track_commit_timestamp,
 (select jsonb_build_object('catalog_xmin',xmin::text,'commit_time',case when current_setting('track_commit_timestamp')='on' then pg_xact_commit_timestamp(xmin) else null end) from pg_constraint where conrelid='private.ai_test_budget_v5'::regclass and conname='ai_test_budget_v5_ceiling_microusd_check') ceiling_constraint_catalog,
 (select jsonb_build_object('all_rows',count(*),'budget_named_rows',count(*) filter(where event_type::text ilike '%budget%' or entity_type::text ilike '%budget%' or event_type::text ilike '%ceiling%' or entity_type::text ilike '%ceiling%'),'budget_named_rows_after_last_5usd',count(*) filter(where created_at>'2026-11-09T01:46:46.356959Z'::timestamptz and (event_type::text ilike '%budget%' or entity_type::text ilike '%budget%' or event_type::text ilike '%ceiling%' or entity_type::text ilike '%ceiling%'))) from private.marketplace_audit_log) marketplace_audit_aggregate,
 (select jsonb_build_object('all_rows',count(*),'budget_named_actions',count(*) filter(where action::text ilike '%budget%' or action::text ilike '%ceiling%')) from private.support_operator_audit_v5) support_audit_aggregate;
rollback;
